prefix=full.split(' public static string Run()')[0].replace('class Banks099','class Finish099')
end=full.split(' // Check text visibility')[1].replace(' // Check text visibility','')
code=prefix+''' public static string Run(){var s=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var root=GameObject.Find("Lobby_Island_Visual_Prototype").transform;var main=root.Find("01_Central_Island");var lab=main.Find("Animal_Laboratory097");var bank=main.Find("Bank_Crystal_Boutique095");var facade=bank.Find("American_Classical_Bank099");var crystal=facade.Find("Landmark_Blue_Crystal099");crystal.Rotate(90,0,0,Space.Self);var gemPoints=V(crystal).Select(facade.InverseTransformPoint).ToArray();crystal.localPosition+=new Vector3(0,4.52f,1.55f)-new Vector3((gemPoints.Min(v=>v.x)+gemPoints.Max(v=>v.x))/2,gemPoints.Min(v=>v.y),(gemPoints.Min(v=>v.z)+gemPoints.Max(v=>v.z))/2);gemPoints=V(crystal).Select(facade.InverseTransformPoint).ToArray();report.AppendLine("Bank: open American classical limestone columns, triangle pediment, navy/gold details; original Gem.prefab uniformly scaled, upright3m landmark. Gem bounds="+(gemPoints.Max(v=>v.y)-gemPoints.Min(v=>v.y)).ToString("F2")+"m high; all16 original merchandise gems retained. Podium9.8x9.4 eight corners, teal, top0.201m; original chamber bases0.205m untouched; console elevated0.2m.");var boards=main.Find("03_Leaderboard_Common").Cast<Transform>().Where(t=>t.name.StartsWith("Leaderboard_")).ToArray();var planks=root.GetComponentsInChildren<Transform>().Where(t=>t.name=="Deck_Plank"&&t.GetComponent<MeshFilter>()!=null).Select(DeckFoot).ToArray();foreach(var b in boards){float gap=planks.Min(p=>Clearance(Footprint(b),p));report.AppendLine(b.name+": main local="+main.InverseTransformPoint(b.position)+" full deck gap="+gap.ToString("F2")+"m");if(gap<1.4f)throw new Exception("Pier clearance failed");}float inner=boards.Min(b=>V(b).Min(v=>Mathf.Abs(main.InverseTransformPoint(v).x)));report.AppendLine("Opening between boards="+(2*inner).ToString("F2")+"m.");
 // Check text visibility'''+end
Path('tools/assets/Finish099.cs.txt').write_text(code,encoding='utf-8')
Path('Library/WorkshopBackups/DB-ON-099/finish.json').write_text(json.dumps({'csharpCode':code,'className':'Finish099','methodName':'Run'}),encoding='utf-8')

